function synchronize(override=null){if(syncBusy){if(override)return syncTask.then(()=>synchronize(override));syncAgain=true;return syncTask}if(blocked)return Promise.resolve(false);syncBusy=true;syncTask=performSync(override);return syncTask}
async function performSync(override){setSave('记录已保存 · 正在加密同步');try{const cfg=override||config()||await register();for(let attempt=0;attempt<4;attempt++){const cloud=await fetchCloud(cfg),combined=merge(state,cloud.state||empty());persist(combined);renderNav();const unchanged=cloud.state&&JSON.stringify(combined)===JSON.stringify(cloud.state);try{if(!unchanged)await putCloud(combined,cloud.revision,cfg);if(override)useConfig(cfg);setSave('已加密同步 · '+new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}));updateCode();if(!document.querySelector('dialog[open]')&&!document.activeElement?.matches('input,textarea,select')&&!$('#workspace').dataset.dirty)render();return true}catch(err){if(err.status!==409||attempt===3)throw err}}return false}catch(err){setSave('本机已保存 · 同步未完成：'+err.message,true);updateCode();return false}finally{syncBusy=false;if(syncAgain){syncAgain=false;clearTimeout(syncTimer);syncTimer=setTimeout(()=>synchronize(),1000)}}}
