const context=document.modelContext;if(context?.registerTool){const lifetime=new AbortController();for(const tool of [{name:'search_research_records',title:'搜索研究记录',description:'Search the current saved papers, full text, extracted evidence and notes. Read-only.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input.query!=='string'||input.query.length>300)throw Error('query must be a string up to 300 characters');query=input.query;$('#global-search').value=query;navigate('memory');return papers().filter(p=>matches(p,query)).map(p=>({id:p.id,title:p.title,url:p.url,status:p.status,topics:p.topics}))}},{name:'import_research_paper',title:'导入论文',description:'Fetch metadata from an arXiv ID or supported research URL and save it in the Research Inbox.',inputSchema:{type:'object',properties:{url:{type:'string'}},required:['url'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},async execute(input){if(!input||typeof input.url!=='string'||!input.url.trim()||input.url.length>2000)throw Error('url must be a nonempty string up to 2000 characters');const result=await api('import',input.url);const saved=saveImported(result.paper,true);render();if(!saved&&!papers().some(p=>identity(p)===identity(result.paper)))throw Error('保存失败');return {saved,duplicate:!saved,title:result.paper.title}}}]){try{Promise.resolve(context.registerTool(tool,{signal:lifetime.signal})).catch(()=>{})}catch{}}addEventListener('pagehide',()=>lifetime.abort(),{once:true})}
